class Star:
    def __init__(self, x):
        self.x = x
        self.y = 60

    def draw(self):
        screen.fillRound(self.x, self.y, 10, 10, "rgb(255,210,0)")

stars = []
for i in range(4):
    stars.append(Star(-60 + i * 40))

def draw():
    screen.clear("rgb(10,10,40)")
    for star in stars:
        star.draw()
